def read_number(n: int) -> str:
    DIGITS = ['', '일', '이', '삼', '사', '오', '육', '칠', '팔', '구']
    UNITS = ['천', '백', '십', '']

    def convert_group(g: int) -> str:
        # g is in 1..9999
        ds = [g // 1000, (g // 100) % 10, (g // 10) % 10, g % 10]
        out = []
        for d, u in zip(ds, UNITS):
            if d == 0:
                continue
            if d == 1 and u:
                out.append(u)
            else:
                out.append(DIGITS[d] + u)
        return ''.join(out)

    if n == 0:
        return '영'

    eok = n // 100000000
    man = (n // 10000) % 10000
    low = n % 10000

    parts = []
    if eok:
        parts.append(convert_group(eok) + '억')
    if man:
        if man == 1:
            parts.append('만')
        else:
            parts.append(convert_group(man) + '만')
    if low:
        parts.append(convert_group(low))
    return ''.join(parts)
